/**
 * Chamada ao servidor para criar a cobranca.
 *
 * ATENCAO: nao ha transpilador neste projeto. O requirejs.php serve amd/src
 * quando nao existe .map, entao ESTE arquivo precisa ser AMD de verdade -
 * sintaxe ES6 aqui vira "No define call" no navegador. O amd/build e uma copia
 * com o nome do modulo dentro do define().
 *
 * @module     paygw_asaas/repository
 * @copyright  2026 Leonardo Della Giustina
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("paygw_asaas/repository", ['core/ajax'], function(Ajax) {

    return {
        /**
         * Pede ao servidor a cobranca no Asaas.
         *
         * O preco NAO viaja daqui: o servidor resolve pelo itemid.
         *
         * @param {String} component
         * @param {String} paymentArea
         * @param {Number} itemId
         * @returns {Promise}
         */
        createCharge: function(component, paymentArea, itemId) {
            return Ajax.call([{
                methodname: 'paygw_asaas_create_charge',
                args: {
                    component: component,
                    paymentarea: paymentArea,
                    itemid: itemId
                }
            }])[0];
        }
    };
});
